{"path":"packages/cli/src/camoufox-adapter.ts","start":38258,"end":39669,"kind":"delivery-boundary","boundary_name":"shutdown-close-extension-error","line_end":1011,"raw":"	const closeGraceMs = options.closeGraceMs ?? CAMOUFOX_CLOSE_GRACE_MS;
	// Drain every idle-stop close still in flight, but never let a wedged close
	// hold the session hostage past the grace period. The grace timer is ref'd
	// so the bound actually elapses in a quiet process, and it is cleared once
	// the drain settles so it cannot hold the session process open afterwards.
	const drainIdleStops = (): Promise<void> => {
		const pending = [...stoppingCloses];
		stoppingCloses.clear();
		if (pending.length === 0) return Promise.resolve();
		let graceTimer: ReturnType<typeof setTimeout> | undefined;
		const grace = new Promise<void>((resolveGrace) => {
			graceTimer = setTimeout(resolveGrace, closeGraceMs);
		});
		return Promise.race([Promise.all(pending).catch(() => undefined), grace])
			.finally(() => {
				clearTimeout(graceTimer);
			})
			.then(() => undefined);
	};
	pi.on("session_start", (_event, context) => {
		basePath = context.cwd;
		// A reused extension instance serves a later session in the same
		// process, whose shutdown must not leave the idle stop disabled.
		idleStop.open();
	});
	pi.on("session_shutdown", async () => {
		idleStop.close();
		basePath = null;
		delegates.clear();
		const loaded = runtime ? await runtime.catch(() => undefined) : undefined;
		runtime = undefined;
		try {
			await loaded?.client.close();
		} finally {
			await drainIdleStops();
		}
	});
","role":"shutdown-close-extension-error"}

{"path":"packages/cli/src/mcp.ts","start":0,"end":1868,"kind":"delivery-boundary","boundary_name":"mcp-contract-no-owned-prose","line_end":54,"raw":"import type { InlineExtension, LoadedMcpConfig, McpServerConfig } from "@earendil-works/pi-coding-agent";

/** Keep script-oriented configurations discoverable through direct tool calls. */
export function deferredMcpConfig(config: McpServerConfig): McpServerConfig {
	return {
		...config,
		exposure: !config.exposure || config.exposure === "codemode" ? "deferred" : config.exposure,
		...(config.toolExposure
			? {
					toolExposure: Object.fromEntries(
						Object.entries(config.toolExposure).map(([name, exposure]) => [
							name,
							exposure === "codemode" ? "deferred" : exposure,
						]),
					),
				}
			: {}),
	};
}

/** Use Pi's MCP client and configuration loader without changing saved server settings. */
export function createDeferredMcpExtension(): InlineExtension {
	return {
		name: "mcp",
		builtin: true,
		replaceable: true,
		async factory(pi) {
			const { createMcpExtension, getAgentDir } = await import("@earendil-works/pi-coding-agent");
			// The exact Pi pin exports the extension factory, but not its configuration loader.
			const { loadMcpConfig } = (await import(
				new URL("./extensions/mcp/config.js", import.meta.resolve("@earendil-works/pi-coding-agent")).href
			)) as {
				loadMcpConfig(options: { agentDir: string; cwd: string; projectTrusted: boolean }): LoadedMcpConfig;
			};
			return createMcpExtension({
				loadConfig: (ctx) => {
					const loaded = loadMcpConfig({
						agentDir: getAgentDir(),
						cwd: ctx.cwd,
						projectTrusted: ctx.isProjectTrusted(),
					});
					return {
						...loaded,
						autoEnableCodemode: false,
						servers: loaded.servers.map((entry) => ({ ...entry, config: deferredMcpConfig(entry.config) })),
					};
				},
			})({
				...pi,
				getMcpServers: () => pi.getMcpServers().map((entry) => ({ ...entry, config: deferredMcpConfig(entry.config) })),
			});
		},
	};
}
","role":"mcp-contract-no-owned-prose"}

