{"path":"packages/cli/src/release-extensions.ts","start":14049,"end":16378,"kind":"delivery-boundary","boundary_name":"optional-resolution-and-init-degradation","line_end":460,"raw":"export function omitOptionalReleaseExtensionFailures(
	result: LoadExtensionsResult,
	status: ReleaseExtensionStatus,
): LoadExtensionsResult {
	const optionalByPath = new Map(
		status.resolvedExtensions
			.filter((record) => record.optional)
			.map((record) => [resolve(record.path), record] as const),
	);
	const errors: LoadExtensionsResult["errors"] = [];
	for (const diagnostic of result.errors) {
		const record = optionalByPath.get(resolve(diagnostic.path));
		if (!record) {
			errors.push(diagnostic);
			continue;
		}
		markReleaseExtensionUnavailable(status, record.packageName, diagnostic.error, diagnostic.path);
	}
	return errors.length === result.errors.length ? result : { ...result, errors };
}

export function formatReleaseExtensionFailure(
	failure: ReleaseExtensionFailure,
	catalog: CatalogBundle = defaultCatalog(),
): string {
	const tools =
		failure.tools.length > 0
			? ` ${catalogText(catalog, RELEASE_EXTENSION_IDS.disabledTools, { tools: failure.tools.join(", ") })}`
			: "";
	return catalogText(catalog, RELEASE_EXTENSION_IDS.unavailable, {
		package: failure.packageName,
		version: failure.packageVersion,
		tools,
		error: failure.error,
	});
}

export function createReleaseExtensionDiagnostics(
	status: ReleaseExtensionStatus,
	runtime?: { warnings(): string[] },
	catalog: CatalogBundle = defaultCatalog(),
): InlineExtension {
	return {
		name: "jouzu-release-extension-diagnostics",
		factory: (pi) => {
			const warned = new Set<string>();
			const warn = (context: { hasUI: boolean; ui: { notify(message: string, level: "warning"): void } }) => {
				for (const message of runtime?.warnings() ?? []) {
					if (warned.has(message)) continue;
					warned.add(message);
					if (context.hasUI) context.ui.notify(message, "warning");
					else console.error(catalogText(catalog, RELEASE_EXTENSION_IDS.warning, { message }));
				}
			};
			pi.on("agent_end", (_event, context) => warn(context));
			pi.on("session_start", (_event, context) => {
				warned.clear();
				warn(context);
				for (const failure of status.degradedExtensions) {
					const message = formatReleaseExtensionFailure(failure, catalog);
					if (context.hasUI) context.ui.notify(message, "warning");
					else console.error(catalogText(catalog, RELEASE_EXTENSION_IDS.warning, { message }));
				}
			});
		},
	};
","role":"optional-resolution-and-init-degradation"}

{"path":"npm:@earendil-works/pi-agent-core@1.4.0/dist/agent-loop.js","start":26128,"end":27203,"kind":"delivery-boundary","boundary_name":"native-tool-exception-result","line_end":613,"raw":"async function executePreparedToolCall(prepared, signal, onUpdate) {
    const updateEvents = [];
    let acceptingUpdates = true;
    const startedAt = performance.now();
    const elapsed = () => Math.round(performance.now() - startedAt);
    try {
        const result = await prepared.tool.execute(prepared.toolCall.id, prepared.args, signal, (partialResult) => {
            if (!acceptingUpdates)
                return;
            updateEvents.push(Promise.resolve(onUpdate(partialResult)));
        });
        const durationMs = elapsed();
        acceptingUpdates = false;
        await Promise.all(updateEvents);
        return { result, isError: result.isError === true, durationMs };
    }
    catch (error) {
        const durationMs = elapsed();
        acceptingUpdates = false;
        await Promise.all(updateEvents);
        return {
            result: createErrorToolResult(error instanceof Error ? error.message : String(error)),
            isError: true,
            durationMs,
        };
    }
    finally {
        acceptingUpdates = false;
    }
","role":"native-tool-exception-result"}

