{"path":"npm:@earendil-works/pi-coding-agent@1.4.0/dist/core/extensions/runner.js","start":33369,"end":34450,"kind":"delivery-boundary","boundary_name":"native-extension-event-error-gate","line_end":840,"raw":"    async emit(event) {
        const ctx = this.createContext();
        let result;
        for (const { ext, handlers } of snapshotEventHandlers(this.extensions, event.type)) {
            for (const handler of handlers) {
                try {
                    const handlerResult = await handler(event, ctx);
                    if (this.isSessionBeforeEvent(event) && handlerResult) {
                        result = handlerResult;
                        if (result.cancel) {
                            return result;
                        }
                    }
                }
                catch (err) {
                    const message = err instanceof Error ? err.message : String(err);
                    const stack = err instanceof Error ? err.stack : undefined;
                    this.emitError({
                        extensionPath: ext.path,
                        event: event.type,
                        error: message,
                        stack,
                    });
                }
            }
        }
        return result;
","role":"native-extension-event-error-gate"}

{"path":"npm:@earendil-works/pi-coding-agent@1.4.0/dist/core/extensions/loader.js","start":24179,"end":25000,"kind":"delivery-boundary","boundary_name":"native-extension-load-error-gate","line_end":578,"raw":"async function loadExtension(extensionPath, cwd, eventBus, runtime, cacheToken) {
    const resolvedPath = resolvePath(extensionPath, cwd, { normalizeUnicodeSpaces: true });
    try {
        const factory = await loadExtensionModule(resolvedPath, cacheToken);
        time(`${extensionPath} module import`, "extensions");
        if (!factory) {
            return { extension: null, error: `Extension does not export a valid factory function: ${extensionPath}` };
        }
        const extension = await initializeExtension(factory, extensionPath, resolvedPath, cwd, eventBus, runtime);
        return { extension, error: null };
    }
    catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        return { extension: null, error: `Failed to load extension: ${message}` };
    }
","role":"native-extension-load-error-gate"}

{"path":"npm:@earendil-works/pi-coding-agent@1.4.0/dist/extensions/mcp/config.js","start":4796,"end":5568,"kind":"delivery-boundary","boundary_name":"native-mcp-config-diagnostics-boundary","line_end":117,"raw":"/**
 * Load global and (when trusted) project MCP configuration. Disabled servers are included with
 * `enabled: false`, so they can be enabled again.
 */
export function loadMcpConfig(options) {
    const state = { servers: new Map(), errors: [] };
    readConfigFile(join(options.agentDir, "mcp.json"), "global", state);
    const projectConfig = options.projectTrusted ? join(options.cwd, CONFIG_DIR_NAME, "mcp.json") : undefined;
    if (projectConfig)
        readConfigFile(projectConfig, "project", state);
    return {
        servers: [...state.servers.values()],
        ...(state.autoEnableCodemode === undefined ? {} : { autoEnableCodemode: state.autoEnableCodemode }),
        errors: state.errors,
        ...(projectConfig ? { projectConfig } : {}),
    };
","role":"native-mcp-config-diagnostics-boundary"}

